inline vec2 IndustrialSocket(int Kind,int Act,int Tick,int Socket) {
 Kind=clamp(Kind,0,3); Act=clamp(Act,0,NUM_IB_ACTS-1); Socket=clamp(Socket,0,2);
 const int End=WardenTicks(IndustrialAct(Act).m_Duration);
 Tick=IndustrialAct(Act).m_Loop ? max(0,Tick)%End : clamp(Tick,0,End);
 const float *p=s_aIndustrialSockets[s_aIndustrialSocketOffsets[Kind][Act]+Tick];
 return vec2(p[Socket*2],p[Socket*2+1]);
}
